CREATE TABLE tb_clientes (id BIGINT GENERATED ALWAYS AS IDENTITY,empresa_id BIGINT NOT NULL,nome VARCHAR(150) NOT NULL,telefone VARCHAR(30) NOT NULL,whatsapp VARCHAR(30) NOT NULL,observacoes TEXT,criado_em TIMESTAMP(6) NOT NULL,PRIMARY KEY(id),CONSTRAINT fk_clientes_empresa FOREIGN KEY(empresa_id) REFERENCES tb_empresas(id));
CREATE TABLE tb_veiculos (id BIGINT GENERATED ALWAYS AS IDENTITY,empresa_id BIGINT NOT NULL,cliente_id BIGINT NOT NULL,marca VARCHAR(80) NOT NULL,modelo VARCHAR(80) NOT NULL,placa VARCHAR(10),cor VARCHAR(40),criado_em TIMESTAMP(6) NOT NULL,PRIMARY KEY(id),CONSTRAINT fk_veiculos_empresa FOREIGN KEY(empresa_id) REFERENCES tb_empresas(id),CONSTRAINT fk_veiculos_cliente FOREIGN KEY(cliente_id) REFERENCES tb_clientes(id));
CREATE TABLE tb_tipos_servicos (id BIGINT GENERATED ALWAYS AS IDENTITY,empresa_id BIGINT NOT NULL,nome VARCHAR(120) NOT NULL,preco_padrao DECIMAL(12,2) NOT NULL,duracao_minutos INT NOT NULL,ativo BOOLEAN NOT NULL,criado_em TIMESTAMP(6) NOT NULL,PRIMARY KEY(id),CONSTRAINT fk_servicos_empresa FOREIGN KEY(empresa_id) REFERENCES tb_empresas(id));
CREATE TABLE tb_ordens_servicos (id BIGINT GENERATED ALWAYS AS IDENTITY,codigo VARCHAR(30) NOT NULL,empresa_id BIGINT NOT NULL,cliente_id BIGINT NOT NULL,veiculo_id BIGINT NOT NULL,tipo_servico_id BIGINT NOT NULL,descricao VARCHAR(255),data DATE NOT NULL,horario TIME NOT NULL,valor DECIMAL(12,2) NOT NULL,observacoes TEXT,status VARCHAR(20) NOT NULL,criado_em TIMESTAMP(6) NOT NULL,atualizado_em TIMESTAMP(6) NOT NULL,PRIMARY KEY(id),CONSTRAINT uk_os_codigo UNIQUE(codigo),CONSTRAINT fk_os_empresa FOREIGN KEY(empresa_id) REFERENCES tb_empresas(id),CONSTRAINT fk_os_cliente FOREIGN KEY(cliente_id) REFERENCES tb_clientes(id),CONSTRAINT fk_os_veiculo FOREIGN KEY(veiculo_id) REFERENCES tb_veiculos(id),CONSTRAINT fk_os_servico FOREIGN KEY(tipo_servico_id) REFERENCES tb_tipos_servicos(id));
CREATE TABLE tb_despesas (id BIGINT GENERATED ALWAYS AS IDENTITY,empresa_id BIGINT NOT NULL,descricao VARCHAR(180) NOT NULL,categoria VARCHAR(40) NOT NULL,valor DECIMAL(12,2) NOT NULL,data DATE NOT NULL,observacoes TEXT,criado_em TIMESTAMP(6) NOT NULL,PRIMARY KEY(id),CONSTRAINT fk_despesas_empresa FOREIGN KEY(empresa_id) REFERENCES tb_empresas(id));
CREATE INDEX idx_clientes_empresa_nome ON tb_clientes(empresa_id,nome); CREATE INDEX idx_veiculos_cliente ON tb_veiculos(empresa_id,cliente_id); CREATE INDEX idx_os_agenda ON tb_ordens_servicos(empresa_id,data,status); CREATE INDEX idx_despesas_data ON tb_despesas(empresa_id,data);
